      const int32_t iDy = ScreenAbsDiff (*pPixelY, sPalette.sEntry[iColor].uiY);
      const int32_t iDu = ScreenAbsDiff (*pPixelU, sPalette.sEntry[iColor].uiU);
      const int32_t iDv = ScreenAbsDiff (*pPixelV, sPalette.sEntry[iColor].uiV);
