  SC_MB_PALETTE     = 1 << 1,
  SC_MB_STATIC      = 1 << 2,
  SC_MB_COPY_LEFT   = 1 << 3,
  SC_MB_COPY_TOP    = 1 << 4
};

typedef struct TagScreenContentPaletteEntry {
  uint8_t uiY;
  uint8_t uiU;
  uint8_t uiV;
